import math
import bisect

def check(x, l, n):
	if x < n:
		return 0
	sa = set({})
	for i in range(len(l)):
		b = l[i] % x
		if b > n or b == 0 or b in sa:
			return 0
		sa.add(b)
	return 1
for _ in range(int(input())):
	n = int(input())
	l = list(map(int, input().strip().split()))
	s = sum(l) - n * (n + 1) // 2
	ans = -1
	for i in range(1, int(s ** (1 / 2)) + 1):
		if s % i == 0:
			if check(i, l, n):
				ans = i
				break
			if check(s // i, l, n):
				ans = s // i
				break
	visit = set()
	for i in l:
		if i >= 1 and i <= n:
			visit.add(i)
	if len(visit) == n:
		ans = n + 1
	if ans != -1:
		print('YES', ans)
	else:
		print('NO')
